    .reg .u64 %rd<80>;
    .reg .u32 %r<220>;
    .reg .f32 %f<64>;
    .reg .pred %p<3>;
    .shared .align 16 .f32 smA[2176];
    .shared .align 16 .f32 smB[2048];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r3, %ctaid.y;
    mov.u32 %r4, %tid.y;
    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %tid.x;
    shl.b32 %r7, %r3, 6;             // base_row = ctaid.y*64
    shl.b32 %r8, %r5, 6;             // base_col = ctaid.x*64
    shl.b32 %r9, %r4, 4;
    add.s32 %r9, %r9, %r6;           // tid_lin = ty*16+tx
    shl.b32 %r10, %r4, 2;            // row_local = ty*4 (thread-local row offset in tile)
    shl.b32 %r11, %r6, 2;            // col_local = tx*4 (thread-local col offset in tile)
    add.s32 %r12, %r7, %r10;         // row0 (global)
    add.s32 %r13, %r12, 1;           // row1
    add.s32 %r14, %r12, 2;           // row2
    add.s32 %r15, %r12, 3;           // row3
    add.s32 %r16, %r8, %r11;         // col0 (global)
    add.s32 %r17, %r16, 1;           // col1
    add.s32 %r18, %r16, 2;           // col2
    add.s32 %r19, %r16, 3;           // col3
