    add.s32 %r173, %r173, %r50;
    st.shared.f32 [%r173], %f2;
    add.s32 %r174, %r172, 68;           // idx2
    shl.b32 %r175, %r174, 2;
    add.s32 %r175, %r175, %r50;
    st.shared.f32 [%r175], %f3;
    add.s32 %r176, %r174, 68;           // idx3
    shl.b32 %r177, %r176, 2;
    add.s32 %r177, %r177, %r50;
    st.shared.f32 [%r177], %f4;
    add.s32 %r67, %r60, 32;          // row_local_a + 32 (pass2 smem row)
    add.s32 %r68, %r7, %r67;         // global row (pass2)
    mad.lo.s32 %r69, %r68, %r2, %r62;
    mul.wide.s32 %rd12, %r69, 4;
    add.s64 %rd13, %rd1, %rd12;
    ld.global.v4.f32 {%f5, %f6, %f7, %f8}, [%rd13];
    mad.lo.s32 %r178, %r62, 68, %r67;   // idx0 = col_group_a*68 + (row_local_a+32)
    shl.b32 %r179, %r178, 2;
    add.s32 %r179, %r179, %r50;
    st.shared.f32 [%r179], %f5;
    add.s32 %r180, %r178, 68;           // idx1
    shl.b32 %r181, %r180, 2;
    add.s32 %r181, %r181, %r50;
    st.shared.f32 [%r181], %f6;
    add.s32 %r182, %r180, 68;           // idx2
    shl.b32 %r183, %r182, 2;
    add.s32 %r183, %r183, %r50;
    st.shared.f32 [%r183], %f7;
    add.s32 %r184, %r182, 68;           // idx3
    shl.b32 %r185, %r184, 2;
    add.s32 %r185, %r185, %r50;
    st.shared.f32 [%r185], %f8;
    // ---- Vectorized load of B tile (K=32 x 64 cols), two passes ----
    shr.u32 %r80, %r9, 4;            // row_local_b = tid_lin >> 4 (0..15)
    and.b32 %r81, %r9, 15;           // col_idx_b = tid_lin & 15 (0..15)
    shl.b32 %r82, %r81, 2;           // col_group_b = col_idx_b*4 (0..60)
    add.s32 %r83, %r8, %r82;         // global col
    mad.lo.s32 %r84, %r80, %r1, %r83; // addr_index = row_local_b*M + global_col
    mul.wide.s32 %rd14, %r84, 4;
    add.s64 %rd15, %rd2, %rd14;
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd15];
    shl.b32 %r85, %r80, 6;
    add.s32 %r86, %r85, %r82;
    shl.b32 %r87, %r86, 2;
    add.s32 %r87, %r87, %r51;
    st.shared.v4.f32 [%r87], {%f9, %f10, %f11, %f12};
    add.s32 %r90, %r80, 16;          // row_local_b + 16 (pass2)
    mad.lo.s32 %r91, %r90, %r1, %r83;
    mul.wide.s32 %rd16, %r91, 4;
    add.s64 %rd17, %rd2, %rd16;
    ld.global.v4.f32 {%f13, %f14, %f15, %f16}, [%rd17];
    shl.b32 %r92, %r90, 6;
    add.s32 %r93, %r92, %r82;
    shl.b32 %r94, %r93, 2;
    add.s32 %r94, %r94, %r51;
    st.shared.v4.f32 [%r94], {%f13, %f14, %f15, %f16};
