_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tallskinny_matmul")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) where one of the
    matrices is tall and skinny (M >> N or N >> M), implemented as a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.is_contiguous() and B.is_contiguous(), "Inputs must be contiguous"

        M, K = A.shape
        K2, M2 = B.shape
        assert K == K2 and M == M2, "Shape mismatch for A @ B"

        C = torch.empty((M, M), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 16, 16
        TILE = 64  # output tile size per CTA (4x4 register-blocked per thread)
        grid_x = math.ceil(M / TILE)
        grid_y = math.ceil(M / TILE)

        module.launch(
            "tallskinny_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

